1	package sem
2	
3	import (
4		"context"
5		"sync"
6	)
7	
8	// providerStreamBatchRecords is how many records a worker accumulates before
9	// one channel handoff, and providerStreamBufferBatches how many full batches a
10	// slot's channel holds. Per-RECORD handoffs made the scheduler the hot path: a
11	// quarter-million records each paid a channel send/receive, and every one that
12	// found the consumer parked (or a tiny buffer full) paid a kernel wakeup —
13	// measured at ~31% of snapshot CPU in runtime.pthread_cond_signal. Batching
14	// divides the handoffs by the batch size; the consumer still sees records in
15	// exactly the order the worker produced them, so output bytes are unchanged.
16	// The bound on admitted-but-unconsumed records per worker is
17	// (providerStreamBufferBatches+1)*providerStreamBatchRecords plus the batch
18	// being filled — a few MB across eight workers, the backpressure the old
19	// 32-record buffer existed to provide, at a size that no longer starves the
20	// producers between consumer wakeups.
21	const (
22		providerStreamBatchRecords  = 256
23		providerStreamBufferBatches = 2
24	)
25	
26	// runIndexedStreamingPipeline preserves index order without retaining an entire
27	// item's output. At most workers items are admitted, each with a bounded batch
28	// buffer. A slow consumer or earlier item backpressures the producers. Results
29	// contain only metadata needed after that item's stream has been consumed.
30	func runIndexedStreamingPipeline[T, R any](
31		ctx context.Context,
32		count, workers int,
33		process func(context.Context, int, func(T)) R,
34		emit func(int, T) error,
35		reduce func(int, R) error,
36	) error {
37		if count == 0 || ctx.Err() != nil {
38			return ctx.Err()
39		}
40		workers = min(count, boundedProviderWorkerCount(workers))
41		workerCtx, cancel := context.WithCancel(ctx)
42		var group sync.WaitGroup
43		defer func() {
44			cancel()
45			group.Wait()
46		}()
47		type slot struct {
48			batches chan []T
49			result  R
50		}
51		start := func(index int) *slot {
52			out := &slot{batches: make(chan []T, providerStreamBufferBatches)}
53			group.Go(func() {
54				defer close(out.batches)
55				batch := make([]T, 0, providerStreamBatchRecords)
56				flush := func() {
57					if len(batch) == 0 {
58						return
59					}
60					full := batch
61					batch = make([]T, 0, providerStreamBatchRecords)
62					select {
63					case out.batches <- full:
64					case <-workerCtx.Done():
65					}
66				}
67				out.result = process(workerCtx, index, func(value T) {
68					if workerCtx.Err() != nil {
69						return
70					}
71					batch = append(batch, value)
72					if len(batch) == providerStreamBatchRecords {
73						flush()
74					}
75				})
76				flush()
77			})
78			return out
79		}
80		slots := make([]*slot, workers)
81		for i := range workers {
82			slots[i] = start(i)
83		}
84		for index := range count {
85			out := slots[index%workers]
86			for {
87				if err := ctx.Err(); err != nil {
88					return err
89				}
90				select {
91				case <-ctx.Done():
92					return ctx.Err()
93				case batch, ok := <-out.batches:
94					if !ok {
95						// Closing the channel publishes the final result, including
96						// when process emitted no values.
97						if err := reduce(index, out.result); err != nil {
98							return err
99						}
100						goto next
101					}
102					for _, value := range batch {
103						if err := emit(index, value); err != nil {
104							return err
105						}
106					}
107				}
108			}
109		next:
110			if next := index + workers; next < count {
111				slots[index%workers] = start(next)
112			} else {
113				slots[index%workers] = nil
114			}
115		}
116		return ctx.Err()
117	}
